--
-- TOC entry 382 (class 1259 OID 18031)
-- Name: api_fhir_r4_historicalsubscription; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."api_fhir_r4_historicalsubscription" (
    "UUID" "uuid" NOT NULL,
    "isDeleted" boolean NOT NULL,
    "Json_ext" "jsonb",
    "DateCreated" timestamp with time zone,
    "DateUpdated" timestamp with time zone,
    "version" integer NOT NULL,
    "DateValidFrom" timestamp with time zone NOT NULL,
    "DateValidTo" timestamp with time zone,
    "ReplacementUUID" "uuid",
    "Status" smallint NOT NULL,
    "Channel" smallint NOT NULL,
    "Endpoint" character varying(255) NOT NULL,
    "Headers" "bytea",
    "Criteria" "jsonb",
    "Expiring" timestamp with time zone NOT NULL,
    "history_id" integer NOT NULL,
    "history_date" timestamp with time zone NOT NULL,
